  KEY `idx_tenant_status` (`tenant_id`,`session_status`) USING BTREE,
  KEY `idx_expire_at` (`expire_at`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='扫码登录会话表';

