-- ----------------------------
DROP TABLE IF EXISTS `biz_goods_change_log`;
CREATE TABLE `biz_goods_change_log` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_id` bigint NOT NULL COMMENT '开单ID',
  `order_no` varchar(32) DEFAULT '' COMMENT '开单编号',
  `node_id` bigint DEFAULT NULL COMMENT '节点ID（如有）',
  `change_type` varchar(32) NOT NULL COMMENT '变更类型：ORDER_CREATE/ORDER_UPDATE/NODE_UPDATE/NODE_STATUS_CHANGE/STATUS_AUTO_UPDATE/ROLLBACK',
  `field_name` varchar(64) DEFAULT '' COMMENT '变更字段名',
  `old_value` json DEFAULT NULL COMMENT '旧值',
  `new_value` json DEFAULT NULL COMMENT '新值',
  `changed_by` bigint DEFAULT NULL COMMENT '操作人ID',
  `changed_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '变更时间',
  `remark` varchar(512) DEFAULT '' COMMENT '备注',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE,
  KEY `idx_node_id` (`node_id`) USING BTREE,
  KEY `idx_change_type` (`change_type`) USING BTREE,
  KEY `idx_changed_at` (`changed_at`) USING BTREE,
  KEY `idx_tenant_order` (`tenant_id`,`order_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='货物变更日志表';

