COMMIT;

-- ----------------------------
-- Table structure for biz_goods_image
-- ----------------------------
DROP TABLE IF EXISTS `biz_goods_image`;
CREATE TABLE `biz_goods_image` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_id` bigint DEFAULT NULL COMMENT '开单ID',
  `item_id` bigint DEFAULT NULL COMMENT '货物明细ID',
  `node_id` bigint DEFAULT NULL COMMENT '加工节点ID',
  `record_id` bigint DEFAULT NULL COMMENT '加工记录ID',
  `image_type` varchar(20) NOT NULL COMMENT '图片类型：SAMPLE-样品照, BEFORE_PROCESS-加工前, AFTER_PROCESS-加工后',
  `image_url` varchar(512) NOT NULL COMMENT '图片URL',
  `thumbnail_url` varchar(512) DEFAULT '' COMMENT '缩略图URL',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小（字节）',
  `ai_features` json DEFAULT NULL COMMENT 'AI提取的图片特征（元数据）',
  `ai_embedding_id` bigint DEFAULT NULL COMMENT 'AI特征向量ID，关联AI服务goods_image_feature.id',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE,
  KEY `idx_item_id` (`item_id`) USING BTREE,
  KEY `idx_record_id` (`record_id`) USING BTREE,
  KEY `idx_image_type` (`image_type`) USING BTREE,
  KEY `idx_tenant_item_type` (`tenant_id`,`item_id`,`image_type`) USING BTREE,
  KEY `idx_ai_embedding_id` (`ai_embedding_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='货物图片表';

