COMMIT;

-- ----------------------------
-- Table structure for biz_goods_order
-- ----------------------------
DROP TABLE IF EXISTS `biz_goods_order`;
CREATE TABLE `biz_goods_order` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_no` varchar(32) NOT NULL COMMENT '开单编号，格式：GDyyyyMMddXXXX',
  `order_date` date NOT NULL COMMENT '开单日期',
  `customer_id` bigint NOT NULL COMMENT '客户公司ID（关联biz_customer.id）',
  `customer_name` varchar(128) DEFAULT '' COMMENT '客户公司名称，冗余字段便于查询',
  `department_id` bigint NOT NULL COMMENT '开单部门ID（关联sys_dept.id）',
  `department_name` varchar(64) DEFAULT '' COMMENT '开单部门名称，冗余字段',
  `status` varchar(20) NOT NULL DEFAULT 'DRAFT' COMMENT '状态：DRAFT-草稿, PENDING_DISTRIBUTE-待分发, PROCESSING-加工中, COMPLETED-已完成, CANCELLED-已取消',
  `total_items` int NOT NULL DEFAULT '0' COMMENT '货物明细总数',
  `total_quantity` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '货物总数量',
  `remark` varchar(512) DEFAULT '' COMMENT '开单备注',
  `operator_id` bigint DEFAULT NULL COMMENT '开单人ID',
  `operator_name` varchar(64) DEFAULT '' COMMENT '开单人姓名，冗余字段',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交时间',
  `distributed_at` datetime DEFAULT NULL COMMENT '分发时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  `accepted_at` datetime DEFAULT NULL COMMENT '接货时间（首个节点开始接货时记录）',
  `delivering_at` datetime DEFAULT NULL COMMENT '送货时间（首个节点进入送货状态时记录）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tenant_order_no` (`tenant_id`,`order_no`) USING BTREE,
  KEY `idx_tenant_customer` (`tenant_id`,`customer_id`) USING BTREE,
  KEY `idx_tenant_status` (`tenant_id`,`status`) USING BTREE,
  KEY `idx_tenant_date` (`tenant_id`,`order_date`) USING BTREE,
  KEY `idx_order_no` (`order_no`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='货物开单主表';

-- ----------------------------
-- Records of biz_goods_order
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for biz_goods_order_item
-- ----------------------------
DROP TABLE IF EXISTS `biz_goods_order_item`;
CREATE TABLE `biz_goods_order_item` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_id` bigint NOT NULL COMMENT '开单ID，关联 biz_goods_order.id',
  `item_name` varchar(128) NOT NULL COMMENT '货物名称',
  `quantity` decimal(18,4) NOT NULL COMMENT '原始数量',
  `unit` varchar(16) NOT NULL DEFAULT '个' COMMENT '计量单位：个/件/kg/米/盒等',
  `unit_price` decimal(18,4) DEFAULT '0.0000' COMMENT '单价（元）',
  `total_price` decimal(24,4) DEFAULT '0.0000' COMMENT '总价 = quantity × unit_price（创建/更新时自动计算）',
  `specification` varchar(128) DEFAULT '' COMMENT '规格型号',
  `material` varchar(64) DEFAULT '' COMMENT '材质',
  `photo_urls` json DEFAULT NULL COMMENT '样品照片URL列表，JSON数组格式',
  `remark` varchar(512) DEFAULT '' COMMENT '货物备注',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE,
  KEY `idx_tenant_item_name` (`tenant_id`,`item_name`) USING BTREE,
  KEY `idx_item_name` (`item_name`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='货物开单明细表';

-- ----------------------------
-- Records of biz_goods_order_item
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for biz_goods_order_version
-- ----------------------------
DROP TABLE IF EXISTS `biz_goods_order_version`;
CREATE TABLE `biz_goods_order_version` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_id` bigint NOT NULL COMMENT '开单ID',
  `version_no` int NOT NULL COMMENT '版本号',
  `order_no` varchar(32) DEFAULT '' COMMENT '开单编号，冗余',
  `customer_id` bigint DEFAULT NULL COMMENT '客户公司ID',
  `customer_name` varchar(128) DEFAULT '' COMMENT '客户公司名称',
  `department_id` bigint DEFAULT NULL COMMENT '开单部门ID',
  `department_name` varchar(64) DEFAULT '' COMMENT '开单部门名称',
  `status` varchar(20) DEFAULT '' COMMENT '开单状态快照',
  `total_items` int DEFAULT '0' COMMENT '货物明细总数',
  `total_quantity` decimal(18,4) DEFAULT '0.0000' COMMENT '货物总数量',
  `remark` varchar(512) DEFAULT '' COMMENT '开单备注',
  `operator_id` bigint DEFAULT NULL COMMENT '开单人ID',
  `operator_name` varchar(64) DEFAULT '' COMMENT '开单人姓名',
  `changed_by` bigint DEFAULT NULL COMMENT '修改人ID',
  `changed_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `change_summary` varchar(512) DEFAULT '' COMMENT '变更摘要',
  `full_snapshot` json DEFAULT NULL COMMENT '完整开单快照（含items）',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE,
  KEY `idx_order_version` (`order_id`,`version_no`) USING BTREE,
  KEY `idx_tenant_order` (`tenant_id`,`order_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='开单版本历史表';

