-- Records of biz_goods_order_version
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for biz_goods_process_node
-- ----------------------------
DROP TABLE IF EXISTS `biz_goods_process_node`;
CREATE TABLE `biz_goods_process_node` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `order_id` bigint NOT NULL COMMENT '开单ID',
  `order_no` varchar(32) DEFAULT '' COMMENT '开单编号，冗余便于查询',
  `item_id` bigint NOT NULL COMMENT '货物明细ID，关联 biz_goods_order_item.id',
  `item_name` varchar(128) DEFAULT '' COMMENT '货物名称，冗余便于查询',
  `department_id` bigint NOT NULL COMMENT '加工部门ID（关联sys_dept.id）',
  `department_name` varchar(64) DEFAULT '' COMMENT '加工部门名称，冗余字段',
  `node_order` int NOT NULL DEFAULT '0' COMMENT '节点排序号，决定加工顺序',
  `status` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT '节点状态：PENDING-待处理, ACCEPTING-开始接货, PROCESSING-加工中, PROCESSED-加工完成, DELIVERING-送货中, DRIVER_DELIVERED-司机送达, COMPLETED-完成',
  `original_quantity` decimal(18,4) NOT NULL COMMENT '加工前数量（来自货物明细）',
  `processed_quantity` decimal(18,4) DEFAULT NULL COMMENT '加工后数量',
  `loss_quantity` decimal(18,4) DEFAULT NULL COMMENT '损耗数量 = original - processed',
  `loss_rate` decimal(5,4) DEFAULT NULL COMMENT '损耗率 = loss_quantity / original_quantity（小数表示，如0.02表示2%）',
  `remark` varchar(512) DEFAULT '' COMMENT '加工备注',
  `operator_id` bigint DEFAULT NULL COMMENT '加工操作人ID',
  `operator_name` varchar(64) DEFAULT '' COMMENT '加工操作人姓名',
  `processed_at` datetime DEFAULT NULL COMMENT '加工完成时间',
  `rollback_count` int NOT NULL DEFAULT '0' COMMENT '回退次数',
  `rollback_reason` varchar(512) DEFAULT '' COMMENT '回退原因',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE,
  KEY `idx_item_id` (`item_id`) USING BTREE,
  KEY `idx_department_id` (`department_id`) USING BTREE,
  KEY `idx_tenant_item_dept` (`tenant_id`,`item_name`(32),`department_id`) USING BTREE,
  KEY `idx_node_status` (`status`) USING BTREE,
  KEY `idx_node_order` (`node_order`) USING BTREE,
  KEY `idx_tenant_node_status` (`tenant_id`,`status`) USING BTREE,
  KEY `idx_tenant_order` (`tenant_id`,`order_id`) USING BTREE,
  KEY `idx_tenant_operator` (`tenant_id`,`operator_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='货物加工节点表';

-- ----------------------------
-- Records of biz_goods_process_node
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for biz_goods_process_node_version
-- ----------------------------
DROP TABLE IF EXISTS `biz_goods_process_node_version`;
CREATE TABLE `biz_goods_process_node_version` (
  `id` bigint NOT NULL COMMENT '主键ID',
