  `department_id` bigint DEFAULT NULL COMMENT '加工部门ID',
  `department_name` varchar(64) DEFAULT '' COMMENT '加工部门名称',
  `node_order` int DEFAULT '0' COMMENT '节点排序',
  `status` varchar(20) DEFAULT '' COMMENT '节点状态快照',
  `original_quantity` decimal(18,4) DEFAULT NULL COMMENT '原始数量',
  `processed_quantity` decimal(18,4) DEFAULT NULL COMMENT '加工后数量',
  `loss_quantity` decimal(18,4) DEFAULT NULL COMMENT '损耗数量',
  `loss_rate` decimal(5,4) DEFAULT NULL COMMENT '损耗率 = loss / original（小数表示，如0.02表示2%）',
  `remark` varchar(512) DEFAULT '' COMMENT '加工备注',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) DEFAULT '' COMMENT '操作人姓名',
  `processed_at` datetime DEFAULT NULL COMMENT '加工完成时间',
  `version_no` int NOT NULL COMMENT '版本号',
  `changed_by` bigint DEFAULT NULL COMMENT '修改人ID',
  `changed_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `change_summary` varchar(512) DEFAULT '' COMMENT '变更摘要',
  `full_snapshot` json DEFAULT NULL COMMENT '完整节点快照',
