  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tenant_role_menu` (`tenant_id`,`role_id`,`menu_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='角色菜单关联表';

